tools.example:
g = RandomGraph[{20, 40}];
GraphicsRow[Graph[g, GraphLayout -> #] & /@ {"SpringElectricalEmbedding", "CircularEmbedding", "SpectralEmbedding"}]
coords = GraphEmbedding[g, "SpringEmbedding"]

g = Graph[{1 <-> 2, 2 <-> 3, 1 <-> 3}, EdgeWeight -> {1, 1, 5}, VertexCoordinates -> {{0, 0}, {1, 0}, {1, 1}}];
FindShortestPath[g, 1, 3] (* {1, 2, 3} *)
WeightedAdjacencyMatrix[g] // MatrixForm

d = {{Infinity, 3, Infinity}, {3, Infinity, 1}, {Infinity, 1, Infinity}};
g = WeightedAdjacencyGraph[{"a", "b", "c"}, d, VertexLabels -> "Name", EdgeLabels -> "EdgeWeight"];
GraphDistance[g, "a", "c"] (* 4 *)

gs = RandomGraph[BarabasiAlbertGraphDistribution[500, 2], 10];
Mean[GraphDiameter /@ gs]
Histogram[VertexDegree[First[gs]], "Log"]

d = GraphPropertyDistribution[MeanClusteringCoefficient[g], g \[Distributed] BernoulliGraphDistribution[100, 0.05]];
NExpectation[x, x \[Distributed] d]
NProbability[c > 0.3, c \[Distributed] d]

g = Graph[{1 <-> 2, 2 <-> 3}];
g2 = SetProperty[{g, 1 <-> 2}, EdgeWeight -> 5];
PropertyValue[{g2, 1 <-> 2}, EdgeWeight] (* 5 *)
g3 = Annotate[{g2, 2}, "role" -> "hub"]; AnnotationValue[{g3, 2}, "role"]

t = RulesTree[1 -> {2 -> {4, 5}, 3}];
Reap[TreeScan[Sow, t, TreeTraversalOrder -> "BreadthFirst"]][[2, 1]] (* {1, 2, 3, 4, 5} *)
Reap[TreeScan[Sow, t, TreeTraversalOrder -> "BottomUp"]][[2, 1]] (* {4, 5, 2, 3, 1} *)

mesh = DiscretizeRegion[Disk[], MaxCellMeasure -> 0.05];
g = MeshConnectivityGraph[mesh];
HighlightGraph[g, PathGraph[FindShortestPath[g, {0, 1}, {0, 200}]]]
